    getDecisionResults: function() {
		var gr = new GlideRecord('x_846092_decisio_0_customize_decision');
		gr.addQuery('u_id', 'Decisionで承認者を設定_v3');
		gr.addQuery("u_effective_start", "<=", "javascript:gs.endOfToday()");
		gr.query();

        var configuration = {};	
        configuration.u_id = gr.u_id + ''; //氏名
        configuration.u_result_pattern_1 = gr.u_result_pattern_1 + ''; //メールアドレス
		configuration.u_result_step2_1 = gr.u_result_step2_1 + '';
        return JSON.stringify(configuration);

     },


    getEmployeeInfo: function() {
        var userGr = new GlideRecord('sys_user');
        var name = this.getParameter('user');
        userGr.get(name);

        var configuration = {};	
        configuration.name = userGr.name + ''; //氏名
        configuration.email = userGr.email + ''; //メールアドレス

        return JSON.stringify(configuration);
    },
	//decisionのsys_IDを取得
    getSysId: function() {
        var name = this.getParameter('name');
        var gr = new GlideRecord('sys_decision');
        gr.addQuery('name', name);
        gr.query();

        if (gr.next()) {
            return gr.getValue('sys_id');
        }
        return 'No Decision Table found with name: ' + name;
    },


    type: 'DecisionV2Utils'
});
